const restaurants = $input.all();

if (restaurants.length === 0) {
  throw new Error("❌ API Key invalide");
}

const restaurant = restaurants[0].json;
const fields = restaurant.fields || restaurant;

if (fields.Actif === false) {
  throw new Error("❌ Restaurant désactivé");
}

const webhookData = $('Webhook').first().json;

return [{
  json: {
    restaurant_id: restaurant.id,
    restaurant_name: fields['Nom Restaurant'] || fields.Nom || '',
    chatInput: webhookData.body?.message || webhookData.body?.chatInput || '',
    originalBody: webhookData.body,
    originalHeaders: webhookData.headers
  }
}]

const input = $input.first().json;
const restaurantId = input.restaurant_id;
const restaurantName = input.restaurant_name || '';

if (!restaurantId) {
  console.error('❌ Restaurant ID manquant');
  throw new Error('Restaurant non identifié');
}

const globalContext = {
  restaurant_id: restaurantId,
  restaurant_name: restaurantName,
  originalRequest: input.originalBody || {},
  originalHeaders: input.originalHeaders || {},
  chatInput: input.chatInput || '',
  timestamp: new Date().toISOString(),
  requestId: `${restaurantId}_${Date.now()}`
};

console.log(`✅ [${restaurantName}] Contexte initialisé`);

return [{ json: globalContext }];
